변경 요약: 1~100 범위와 큼/작음/정답 피드백 규칙을 구체화하고, HTML/JavaScript 웹 기반으로 플랫폼을 정했으며, 점수·멀티플레이·저장은 MVP 범위 밖으로 뒀습니다.

작업 폴더에 단일 HTML 파일로 만들겠습니다.


<invoke name="Write">
<parameter name="file_path">/private/tmp/claude-501/ptbench/index.html</parameter>
<parameter name="content"><!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>숫자 맞추기 게임</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background: #f3f4f6;
      font-family: -apple-system, BlinkMacSystemFont, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
      color: #111827;
    }
    main {
      width: min(92vw, 380px);
      padding: 28px 24px;
      background: #fff;
      border-radius: 16px;
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
      text-align: center;
    }
    h1 { margin: 0 0 8px; font-size: 1.5rem; }
    p.desc { margin: 0 0 20px; color: #6b7280; }
    form { display: flex; gap: 8px; }
    input {
      flex: 1;
      min-width: 0;
      padding: 12px;
      font-size: 1.1rem;
      border: 2px solid #d1d5db;
      border-radius: 10px;
      text-align: center;
    }
    input:focus { outline: none; border-color: #4f46e5; }
    button {
      padding: 12px 18px;
      font-size: 1rem;
      border: none;
      border-radius: 10px;
      background: #4f46e5;
      color: #fff;
      cursor: pointer;
    }
    button:hover { background: #4338ca; }
    button:disabled { background: #9ca3af; cursor: not-allowed; }
    #message {
      min-height: 3em;
      margin: 20px 0 8px;
      font-size: 1.15rem;
      font-weight: 600;
    }
    #message.high, #message.low { color: #d97706; }
    #message.error { color: #dc2626; }
    #message.win { color: #059669; }
    #attempts { margin: 0 0 16px; color: #6b7280; font-size: 0.9rem; }
    #restart { display: none; background: #059669; }
    #restart:hover { background: #047857; }
  </style>
</head>
<body>
  <main>
    <h1>숫자 맞추기</h1>
    <p class="desc">1부터 100 사이의 숫자를 맞춰보세요.</p>

    <form id="guess-form" novalidate>
      <input id="guess" type="text" inputmode="numeric" autocomplete="off"
             placeholder="숫자 입력" aria-label="추측한 숫자">
      <button id="submit" type="submit">확인</button>
    </form>

    <div id="message" role="status" aria-live="polite"></div>
    <p id="attempts">시도: 0회</p>
    <button id="restart" type="button">다시 하기</button>
  </main>

  <script>
    const MIN = 1;
    const MAX = 100;

    const form = document.getElementById('guess-form');
    const input = document.getElementById('guess');
    const submitBtn = document.getElementById('submit');
    const message = document.getElementById('message');
    const attemptsEl = document.getElementById('attempts');
    const restartBtn = document.getElementById('restart');

    let answer;
    let attempts;
    let finished;

    function newGame() {
      answer = Math.floor(Math.random() * (MAX - MIN + 1)) + MIN;
      attempts = 0;
      finished = false;
      input.value = '';
      input.disabled = false;
      submitBtn.disabled = false;
      restartBtn.style.display = 'none';
      attemptsEl.textContent = '시도: 0회';
      show('', '');
      input.focus();
    }

    function show(text, cls) {
      message.textContent = text;
      message.className = cls;
    }

    function handleGuess(event) {
      event.preventDefault();
      if (finished) return;

      const raw = input.value.trim();

      // 정수가 아닌 입력(빈 값, 소수, 문자 등)
      if (!/^\d+$/.test(raw)) {
        show(`${MIN}~${MAX} 사이의 정수를 입력하세요.`, 'error');
        input.select();
        return;
      }

      const guess = Number(raw);

      // 범위 밖 입력은 시도 횟수에 포함하지 않음
      if (guess < MIN || guess > MAX) {
        show(`${MIN}~${MAX} 범위의 숫자만 입력할 수 있어요.`, 'error');
        input.select();
        return;
      }

      attempts += 1;
      attemptsEl.textContent = `시도: ${attempts}회`;

      if (guess === answer) {
        finished = true;
        show(`정답! ${answer}를 ${attempts}번 만에 맞췄어요 🎉`, 'win');
        input.disabled = true;
        submitBtn.disabled = true;
        restartBtn.style.display = 'inline-block';
        restartBtn.focus();
      } else if (guess > answer) {
        show(`${guess}은(는) 큼 — 더 작은 숫자를 입력하세요.`, 'high');
        input.select();
      } else {
        show(`${guess}은(는) 작음 — 더 큰 숫자를 입력하세요.`, 'low');
        input.select();
      }
    }

    form.addEventListener('submit', handleGuess);
    restartBtn.addEventListener('click', newGame);

    newGame();
  </script>
</body>
</html>
</parameter>
</invoke>
