const fs = require('fs');
const html = fs.readFileSync(process.argv[2], 'utf8');
const js = html.match(/<script>([\s\S]*?)<\/script>/)[1];

const els = {};
const mk = id => els[id] = { id, value: '', textContent: '', className: '', style: {}, disabled: false,
  handlers: {}, addEventListener(t, f) { this.handlers[t] = f; }, focus() {}, select() {} };
['guess-form','guess','submit','message','attempts','restart'].forEach(mk);
const document = { getElementById: id => els[id] };

// 정답을 고정하기 위해 Math.random 대체 (정답 = 42)
const fakeMath = Object.create(Math);
fakeMath.random = () => 41.5 / 100;

new Function('document', 'Math', js)(document, fakeMath);

const guess = v => {
  els.guess.value = v;
  els['guess-form'].handlers.submit({ preventDefault() {} });
  return `${JSON.stringify(v)} → [${els.message.className}] ${els.message.textContent} | ${els.attempts.textContent}`;
};

console.log(guess(''));
console.log(guess('abc'));
console.log(guess('3.5'));
console.log(guess('0'));
console.log(guess('101'));
console.log(guess('-5'));
console.log(guess('50'));
console.log(guess('10'));
console.log(guess(' 42 '));
console.log('입력 비활성화:', els.guess.disabled, '| 다시하기 표시:', els.restart.style.display);
els.restart.handlers.click();
console.log('재시작 후:', els.attempts.textContent, '| 입력 활성화:', !els.guess.disabled);
EOF
